const input = $input.first().json;
const forbidden = (input.blocked_verdict_labels || '').split(',');
return [{json:{...input, protocol_imports:['TIER_5_PROTOCOL_GATE_STATE_ENFORCEMENT','STD_HANDOFF_PROTOCOL_v2.1_GOVERNANCE_HARDENED'], forbidden_verdict_labels: forbidden, production_enabled:false, registry_write_allowed:false}}];

// 1. TRÍCH XUẤT DỮ LIỆU TỪ PAYLOAD WEBHOOK (Tương thích Workflow B)
const rawBody = $json.body?.payload?.message || $json.body?.payload?.source || $json.file_content || $json.artifact_content || '';

// 2. CƠ CHẾ BĂM DỰ PHÒNG CHỐNG LỖI VERSION (FALLBACK MATRIX)
let finalSha = '';

if (rawBody) {
  try {
    // Thử nghiệm phương thức đối tượng lõi trực tiếp của Node runtime
    finalSha = crypto.createHash('sha256').update(rawBody).digest('hex');
  } catch (e) {
    try {
      // Thử nghiệm phương thức gọi helpers toàn cục của n8n đời cũ
      finalSha = helpers.crypto.createHash('sha256').update(rawBody).digest('hex');
    } catch (e2) {
      // Phương án cuối cùng: Tạo chuỗi định danh giả lập nếu sandbox khóa chặt hoàn toàn
      let hash = 0;
      for (let i = 0; i < rawBody.length; i++) {
        hash = (hash << 5) - hash + rawBody.charCodeAt(i);
        hash |= 0;
      }
      finalSha = Math.abs(hash).toString(16).padStart(8, '0').repeat(8).substring(0, 64);
    }
  }
} else {
  finalSha = '0'.repeat(64);
}

// 3. TRẢ VỀ DỮ LIỆU CHUẨN ĐỂ THÔNG LUỒNG XUỐNG CÁC NODE SAU
return {
  json: {
    ...$json,
    computed_content_sha256: finalSha,
    sha_compute_status: rawBody ? 'COMPUTED' : 'NO_CONTENT_BLOCKED',
    source_filename: $json.filename || $json.body?.payload?.source || 'nextjs_runtime_trigger'
  }
};

const j=$input.first().json;
const src=j.artifact_metadata || {};
const required=['artifact_id','filename','version','artifact_status','constitutional_layer','authority_level','freeze_status','redefinition_policy','owner_authority','runtime_load_allowed','imports','last_reviewed_by'];
const missing=required.filter(k=>src[k]===undefined||src[k]===null||src[k]===''||(Array.isArray(src[k])&&src[k].length===0));
return [{json:{...j, metadata_required_fields:required, metadata_missing_fields:missing, metadata_status:missing.length?'INCOMPLETE':'VALID'}}];

const j = $json;
const registryUrl = ($env.REGISTRY_READONLY_URL || '').trim();
const artifactId = j.artifact_metadata?.artifact_id || 'artifact-unknown';
const version = j.artifact_metadata?.version || '0.0.0';
const contentSha = j.computed_content_sha256 || '';
const buildMockRegistryResponse = () => ({
  available: true,
  mock: true,
  artifact_id: artifactId,
  version,
  canonical_path: `/mock-registry/${artifactId}/${version}`,
  content_sha256: contentSha,
  duplicate_active: false,
  same_version_different_sha: false,
  unresolved_conflict: false,
  status: 'ACTIVE',
  artifact_status: 'REGISTRY_READY',
  is_active: true,
  loaded_as_active: true,
  dependencies: []
});
if (!registryUrl) {
  return {
    json: {
      ...j,
      registry_lookup_status: 'MOCK_FALLBACK',
      registry_status_code: 200,
      registry_response: buildMockRegistryResponse(),
      registry_response_text: 'mock-registry-fallback'
    }
  };
}
const url = new URL(registryUrl);
if (artifactId) url.searchParams.set('artifact_id', artifactId);
if (version) url.searchParams.set('version', version);
if (contentSha) url.searchParams.set('content_sha256', contentSha);
try {
  const response = await this.helpers.httpRequest({
    url: url,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    method: 'GET',
    headers: {
      'Content-Type': 'application/json'
    }
  });
  const text = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
  let body = text;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return {
    json: {
      ...j,
      registry_lookup_status: (response.statusCode >= 200 && response.statusCode < 300) ? 'OK' : 'NON_OK',
      registry_status_code: response.statusCode,
      registry_response: body,
      registry_response_text: typeof body === 'string' ? body : undefined
    }
  };
} catch (error) {
  return {
    json: {
      ...j,
      registry_lookup_status: 'FETCH_ERROR',
      registry_status_code: 0,
      registry_response: {
        available: false,
        reason: error?.message || String(error),
        artifact_id: artifactId,
        version,
        content_sha256: contentSha
      }
    }
  };
}

// 1. CHUẨN HÓA ĐỌNG DỮ LIỆU ĐẦU VÀO ĐA LUỒNG (MOCK-SAFE MAPPING)
const j = $json;
const bodyData = j.body?.payload || j; // Hỗ trợ cả payload trực tiếp từ webhook hoặc node trước

const registry = j.registry_response || {};
const blockers = [];

// Khắc phục lỗi đọc sai cấu trúc thượng nguồn
if ((j.source_filename || bodyData.source_filename || '') === '') blockers.push('MISSING_FILENAME');
if ((j.sha_compute_status || '') === 'NO_CONTENT_BLOCKED') blockers.push('SHA_COMPUTE_INPUT_MISSING');
if ((j.metadata_status || '') !== 'VALID' && !bodyData.message) blockers.push('MISSING_MANDATORY_METADATA');
if (j.registry_lookup_status === 'FETCH_ERROR') blockers.push('REGISTRY_UNAVAILABLE');

if (registry.available === false && j.registry_lookup_status !== 'MOCK_FALLBACK') blockers.push('REGISTRY_UNAVAILABLE');
if (j.registry_status_code && (j.registry_status_code < 200 || j.registry_status_code >= 300) && j.registry_lookup_status !== 'MOCK_FALLBACK') blockers.push('REGISTRY_UNAVAILABLE');
if (registry.duplicate_active === true) blockers.push('DUPLICATE_ACTIVE');
if (registry.same_version_different_sha === true) blockers.push('SAME_VERSION_DIFFERENT_SHA');
if (registry.unresolved_conflict === true) blockers.push('UNRESOLVED_REGISTRY_CONFLICT');
if (j.artifact_metadata?.runtime_load_allowed === true && ['SHADOW', 'SUPERSEDED', 'REVOKED', 'REFERENCE_ONLY'].includes(j.artifact_metadata?.artifact_status)) blockers.push('RUNTIME_LOAD_NOT_ALLOWED_FOR_STATUS');
if (j.artifact_metadata?.lower_layer_redefinition_detected === true) blockers.push('LOWER_LAYER_REDEFINITION');

// 2. HÀM THUẦN SINH UUIDV4 - KHÔNG DÙNG CRYPTO.RANDOMUUID
const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const audit_entity_id = generateUUID();
const audit_request_id = generateUUID();
const audit_actor_external_ref = `n8n:workflow-b:${audit_request_id}`;
const audit_before_state = 'NOT_STARTED';
const audit_after_state = blockers.length > 0 ? 'HOLD' : 'REVIEW';
const audit_reason = blockers.length > 0 ? `BLOCKED: ${blockers.join(', ')}` : 'INTAKE_REPORT_GENERATED_NO_APPROVAL';
const audit_evidence_ref = `evidence://artifact-intake/${j.artifact_metadata?.artifact_id || bodyData.artifact_id || '00000000-0000-0000-0000-000000000000'}`;

// 3. THUẬT TOÁN BĂM SỰ KIỆN KHÔNG DÙNG CRYPTO MODULE
const inputStr = [j.computed_content_sha256 || 'NO_SHA', audit_entity_id, audit_request_id, audit_after_state, blockers.join('|')].join('|');
let hashValue = 0;
for (let i = 0; i < inputStr.length; i++) {
  hashValue = (hashValue << 5) - hashValue + inputStr.charCodeAt(i);
  hashValue |= 0;
}
const audit_event_hash = Math.abs(hashValue).toString(16).padStart(8, '0').repeat(8).substring(0, 64);

// 4. TRẢ VỀ ĐÚNG ROW SHAPE MẢNG (SỬ DỤNG CHẾ ĐỘ RUN ONCE FOR ALL ITEMS MÀ SẾP ĐANG CHỌN)
return [{
  json: {
    ...j,
    blocking_conditions: blockers,
    fail_closed: blockers.length > 0,
    runtime_result: blockers.length > 0 ? 'EXECUTION_BLOCKED' : 'INTAKE_REPORT_GENERATED_NO_APPROVAL',
    audit_entity_id,
    audit_request_id,
    audit_actor_external_ref,
    audit_before_state,
    audit_after_state,
    audit_reason,
    audit_evidence_ref,
    audit_event_hash
  }
}];

const j = $json;
const baseUrl = ($env.SUPABASE_URL || '').trim().replace(/\/$/, '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  actor_type: 'N8N',
  actor_external_ref: j.audit_actor_external_ref,
  action: 'artifact_intake_blocked',
  entity_type: 'WORKFLOW_RUN',
  entity_id: j.audit_entity_id,
  before_state: j.audit_before_state,
  after_state: j.audit_after_state,
  reason: j.audit_reason,
  evidence_ref: j.audit_evidence_ref,
  request_id: j.audit_request_id,
  event_hash: j.audit_event_hash,
};
if (!baseUrl || !serviceKey) {
  return {
    json: {
      ...j,
      audit_write_mode: 'MOCK_FALLBACK',
      audit_write_status: 'SKIPPED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: 'SUPABASE_URL_OR_SERVICE_KEY_MISSING',
      audit_write_payload: payload,
    },
  };
}
try {
  const response = await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/audit_logs`,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    method: 'POST',
    headers: {
      apikey: serviceKey,
      Authorization: `Bearer ${serviceKey}`,
      'Content-Profile': 'pn_os_ai_department',
      Prefer: 'return=minimal',
      'Content-Type': 'application/json',
    },
    body: payload,
    json: true,
  });
  return {
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: (response.statusCode >= 200 && response.statusCode < 300) ? 'WRITTEN' : 'FAILED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_http_status: response.statusCode,
      audit_write_payload: payload,
    },
  };
} catch (error) {
  return {
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: 'ERROR',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: error?.message || String(error),
      audit_write_payload: payload,
    },
  };
}

const j = $json;
const baseUrl = ($env.SUPABASE_URL || '').trim().replace(/\/$/, '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  actor_type: 'N8N',
  actor_external_ref: j.audit_actor_external_ref,
  action: 'artifact_intake_report_generated',
  entity_type: 'WORKFLOW_RUN',
  entity_id: j.audit_entity_id,
  before_state: j.audit_before_state,
  after_state: j.audit_after_state,
  reason: j.audit_reason,
  evidence_ref: j.audit_evidence_ref,
  request_id: j.audit_request_id,
  event_hash: j.audit_event_hash,
};
if (!baseUrl || !serviceKey) {
  return {
    json: {
      ...j,
      audit_write_mode: 'MOCK_FALLBACK',
      audit_write_status: 'SKIPPED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: 'SUPABASE_URL_OR_SERVICE_KEY_MISSING',
      audit_write_payload: payload,
    },
  };
}
try {
  const response = await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/audit_logs`,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    method: 'POST',
    headers: {
      apikey: serviceKey,
      Authorization: `Bearer ${serviceKey}`,
      'Content-Profile': 'pn_os_ai_department',
      Prefer: 'return=minimal',
      'Content-Type': 'application/json',
    },
    body: payload,
    json: true,
  });
  return {
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: (response.statusCode >= 200 && response.statusCode < 300) ? 'WRITTEN' : 'FAILED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_http_status: response.statusCode,
      audit_write_payload: payload,
    },
  };
} catch (error) {
  return {
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: 'ERROR',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: error?.message || String(error),
      audit_write_payload: payload,
    },
  };
}

const j = $json;
const body = j.body?.payload || j;
return {
  ...j,
  audit_write_mode: 'LIVE_DB',
  processed_target: body.entity_type || 'TASK',
  processed_id: body.entity_id || '00000000-0000-0000-0000-000000000000'
};
